schema_setup_sql:
DROP TABLE IF EXISTS treatments CASCADE;
DROP TABLE IF EXISTS doctors CASCADE;
DROP TABLE IF EXISTS patients CASCADE;

CREATE TABLE doctors (id SERIAL PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE patients (id SERIAL PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE treatments (patient_id INTEGER REFERENCES patients(id), doctor_id INTEGER REFERENCES doctors(id), condition TEXT NOT NULL);

INSERT INTO doctors VALUES (1, 'Dr. Smith'), (2, 'Dr. Jones'), (3, 'Dr. Taylor');
INSERT INTO patients VALUES (1, 'Alice'), (2, 'Bob'), (3, 'Charlie');
INSERT INTO treatments VALUES (1, 1, 'Flu'), (2, 1, 'Cold'), (3, 2, 'Flu'), (1, 3, 'Flu');

reference_solution_sql:
SELECT DISTINCT d.id AS doctor_id, d.name AS doctor_name
FROM doctors d
WHERE d.id IN (SELECT t.doctor_id FROM treatments t WHERE t.condition = 'Flu');

